  "Too many tries in a short time. Please wait {n} minutes and try again.": "తక్కువ సమయంలో చాలా ప్రయత్నాలు. దయచేసి {n} నిమిషాలు ఆగి మళ్ళీ ప్రయత్నించండి.",
  "Type your username and your password.": "మీ యూజర్‌నేమ్, పాస్‌వర్డ్ టైప్ చేయండి.",
  "Type your mobile number, email or username.": "మీ మొబైల్ నంబర్, ఈమెయిల్ లేదా యూజర్‌నేమ్ టైప్ చేయండి.",
  "Your sign-in has timed out. Sign in again.": "మీ సైన్ ఇన్ సమయం ముగిసింది. మళ్ళీ సైన్ ఇన్ చేయండి.",
