  "The preview shows": "ప్రివ్యూలో కనిపించేది",
  ". The PDF is exactly what prints.": ". ప్రింట్ అయ్యేది సరిగ్గా PDFలో ఉన్నట్లే.",
  "Preview with a real record:": "నిజమైన రికార్డుతో ప్రివ్యూ:",
