  "Nobody found. Try part of the name.": "ఎవరూ దొరకలేదు. పేరులో కొంత భాగం ప్రయత్నించండి.",
  "Back to sample data": "నమూనా డేటాకు తిరిగి",
  "Background picture": "నేపథ్య చిత్రం",
  "Remove picture": "చిత్రం తీసివేయండి",
  "Optional. A light picture keeps the text easy to read. JPG or PNG, at most 10 MB.": "ఐచ్ఛికం. లేత చిత్రం అక్షరాలను సులువుగా చదవనిస్తుంది. JPG లేదా PNG, గరిష్ఠంగా 10 MB.",
  "Printed by": "ప్రింట్ చేసేది",
  "You can see this design and preview it with real records. The School Admin changes it.": "మీరు ఈ డిజైన్‌ను చూసి నిజమైన రికార్డులతో ప్రివ్యూ చేయవచ్చు. దీన్ని స్కూల్ అడ్మిన్ మారుస్తారు.",
  "Not changed yet. Documents use the ready Classic design until you save.": "ఇంకా మార్చలేదు. మీరు సేవ్ చేసేవరకు పత్రాలు సిద్ధమైన క్లాసిక్ డిజైన్ వాడతాయి.",
  "Documents printed from now on use version": "ఇప్పటి నుండి ప్రింట్ అయ్యే పత్రాలు ఈ వెర్షన్ వాడతాయి:",
  ". The design in use now stays in the list, so you can switch back.": ". ఇప్పుడు వాడుతున్న డిజైన్ జాబితాలో ఉంటుంది, కాబట్టి మళ్ళీ మారవచ్చు.",
  "Required": "తప్పనిసరి",
  "(only when the field is shown)": "(ఖాళీ కనిపించినప్పుడు మాత్రమే)",
  "Show only when (optional)": "ఎప్పుడు మాత్రమే చూపించాలి (ఐచ్ఛికం)",
  "Add a choice or yes-or-no field first; then this field can show only for one of its answers.": "ముందు ఎంపిక లేదా అవును-కాదు ఖాళీని జోడించండి; అప్పుడు ఈ ఖాళీ దాని ఒక జవాబుకే కనిపించవచ్చు.",
  "Move": "జరపండి",
  "up": "పైకి",
  "down": "కిందకి",
  "no longer shows on forms. Answers already given are kept, and you can restore the field later.": "ఇక ఫారాల్లో కనిపించదు. ఇచ్చిన జవాబులు ఉంటాయి, ఈ ఖాళీని తర్వాత తిరిగి తేవచ్చు.",
  "The field leaves this draft. Answers to versions already published are kept.": "ఖాళీ ఈ డ్రాఫ్ట్ నుండి తొలగుతుంది. ఇప్పటికే విడుదలైన వెర్షన్ల జవాబులు ఉంటాయి.",
  "The form with its": "ఫారం, దాని",
  "field": "ఖాళీలతో",
  "becomes the version people fill in. Answers already given stay with the version they were given on.": "ప్రజలు నింపే వెర్షన్ అవుతుంది. ఇచ్చిన జవాబులు అవి ఇచ్చిన వెర్షన్‌తోనే ఉంటాయి.",
  "Nobody can fill in": "దీన్ని ఇక ఎవరూ నింపలేరు:",
  "any more. Answers already given are kept. You can restore it later.": ". ఇచ్చిన జవాబులు ఉంటాయి. తర్వాత తిరిగి తేవచ్చు.",
  "Your school's rule for": "దీనికి మీ స్కూల్ నియమం:",
  "is set aside and the default is used for new requests. Requests already waiting keep their approver.": "పక్కన పెట్టి, కొత్త అభ్యర్థనలకు డిఫాల్ట్ వాడతారు. ఇప్పటికే వేచి ఉన్న అభ్యర్థనలకు అదే ఆమోదకుడు ఉంటారు.",
  "Your rule": "మీ నియమం",
  "Default": "డిఫాల్ట్",
  "Changed": "మార్చారు",
  "Edit": "మార్చండి",
  "Add one for anything your school records that the standard form does not have, like a house or a bus pass number.": "ప్రామాణిక ఫారంలో లేనిది మీ స్కూల్ నమోదు చేస్తే, ఉదా. హౌస్ లేదా బస్ పాస్ నంబర్, ఒకటి జోడించండి.",
  "Restricted": "పరిమితం",
