  "The AI only prepares and suggests. A person always checks before anything is saved or sent.": "AI సిద్ధం చేసి సూచిస్తుంది మాత్రమే. ఏదైనా సేవ్ లేదా పంపే ముందు ఎప్పుడూ ఒక వ్యక్తి తనిఖీ చేస్తారు.",
