  "It is taken off the list and stops sending reminders. Added by mistake? This is the way to take it off. You can bring it back from “Show removed” if you need it.": "ఇది జాబితా నుండి తొలగి, గుర్తుచేతలు ఆగిపోతాయి. పొరపాటున జోడించారా? తీసివేసే మార్గం ఇదే. అవసరమైతే “తొలగించినవి చూపించు” నుండి తిరిగి తేవచ్చు.",
