  "Optional. Guardians who read this language see it; otherwise they see the first one.": "ఐచ్ఛికం. ఈ భాష చదివే తల్లిదండ్రులు దీన్ని చూస్తారు; మిగతావారు మొదటిది చూస్తారు.",
