  "Privacy · Data Backup & Security": "గోప్యత · డేటా బ్యాకప్ & భద్రత",
  "Under the DPDP Act 2023, personal data is kept only as long as it is needed. Some records must be kept by law.": "DPDP చట్టం 2023 ప్రకారం వ్యక్తిగత డేటా అవసరమైనంత కాలమే ఉంచుతారు. కొన్ని రికార్డులు చట్టం ప్రకారం ఉంచాలి.",
  "A person's data": "ఒక వ్యక్తి డేటా",
  "When a parent, student or staff member asks to see or remove their data. Removal needs approval and is written to the audit log.": "తల్లిదండ్రులు, విద్యార్థి లేదా సిబ్బంది తమ డేటా చూడాలని లేదా తొలగించాలని అడిగినప్పుడు. తొలగింపుకు ఆమోదం కావాలి, ఆడిట్ లాగ్‌లో రాస్తారు.",
  "Check the numbers marked below.": "కింద గుర్తించిన సంఖ్యలు తనిఖీ చేయండి.",
  "Check the field marked below.": "కింద గుర్తించిన ఖాళీ తనిఖీ చేయండి.",
  "Saved. The numbers are compared below.": "సేవ్ అయింది. సంఖ్యలను కింద పోల్చారు.",
  "Go-live check · Switching to School OS": "గో-లైవ్ తనిఖీ · School OSకు మారడం",
  "Families": "కుటుంబాలు",
  "Parents grouped by phone number": "ఫోన్ నంబర్ వారీగా తల్లిదండ్రులు",
  "Students in each class": "ప్రతి తరగతిలో విద్యార్థులు",
  "Compare with the class registers or your old software's class strength report.": "తరగతి రిజిస్టర్లు లేదా పాత సాఫ్ట్‌వేర్ తరగతి సంఖ్య నివేదికతో పోల్చండి.",
  "Worth a look": "చూడదగినవి",
  "Problems in red stop going live; the others do not.": "ఎరుపు సమస్యలు గో లైవ్‌ను ఆపుతాయి; మిగతావి ఆపవు.",
  "Everything matches.": "అంతా సరిపోలింది.",
  "Fees due before go-live": "గో-లైవ్‌కు ముందు బాకీ ఫీజు",
  "The fee plans cover the whole year. Months before the go-live date were the old software's, and are never billed twice.": "ఫీజు ప్రణాళికలు మొత్తం సంవత్సరానికి ఉంటాయి. గో-లైవ్ తేదీకి ముందు నెలలు పాత సాఫ్ట్‌వేర్‌వి, ఎప్పుడూ రెండుసార్లు బిల్ అవ్వవు.",
  "What your old software says": "మీ పాత సాఫ్ట్‌వేర్ ఏం చెబుతోంది",
  "Type the totals from the old software or registers. School OS shows any difference.": "పాత సాఫ్ట్‌వేర్ లేదా రిజిస్టర్ల నుండి మొత్తాలు టైప్ చేయండి. ఏ తేడా ఉన్నా School OS చూపిస్తుంది.",
  "Go live": "గో లైవ్",
  "On going live, the move-in is marked done, and the go-live summary is kept. Records can still be added and imports undone.": "గో లైవ్ అయ్యాక మారే పని పూర్తైనట్లు గుర్తిస్తారు, గో-లైవ్ సారాంశం ఉంచుతారు. రికార్డులు ఇంకా జోడించవచ్చు, దిగుమతులు రద్దు చేయవచ్చు.",
  "Money brought in": "తెచ్చిన డబ్బు",
  "Compare with the old software's balance and collection reports.": "పాత సాఫ్ట్‌వేర్ బాకీ, వసూలు నివేదికలతో పోల్చండి.",
  "Old dues it shows (₹)": "అది చూపించే పాత బాకీలు (₹)",
  "Fees collected this year (₹)": "ఈ సంవత్సరం వసూలైన ఫీజు (₹)",
  "Advance paid ahead (₹)": "ముందుగా చెల్లించిన అడ్వాన్స్ (₹)",
  "Cash in hand on go-live (₹)": "గో-లైవ్ నాటికి చేతిలో నగదు (₹)",
  "Bank balances on go-live (₹)": "గో-లైవ్ నాటికి బ్యాంక్ నిల్వలు (₹)",
  "Old software (or Excel, or paper registers)": "పాత సాఫ్ట్‌వేర్ (లేదా Excel, లేదా కాగితం రిజిస్టర్లు)",
  "Students it shows": "అది చూపించే విద్యార్థులు",
