  "Archive": "ఆర్కైవ్ చేయండి",
  "Heading and colours": "శీర్షిక, రంగులు",
  "Show the school logo": "స్కూల్ లోగో చూపించు",
  "The logo is set in School Profile.": "లోగో స్కూల్ ప్రొఫైల్‌లో ఏర్పాటు చేస్తారు.",
  "Faint logo behind the text": "అక్షరాల వెనుక లేత లోగో",
  "ID card layout": "ID కార్డు అమరిక",
  "Cards are printed several to an A4 sheet, ready to cut.": "కార్డులు ఒక A4 షీట్‌పై కొన్ని కొన్ని ప్రింట్ అవుతాయి, కత్తిరించడానికి సిద్ధంగా.",
  "Show the academic year": "విద్యా సంవత్సరం చూపించు",
