  "Details shown": "చూపించే వివరాలు",
  "Tick what to show. The name and photo always show on cards.": "చూపించాల్సినవి టిక్ చేయండి. పేరు, ఫోటో కార్డులపై ఎప్పుడూ కనిపిస్తాయి.",
  "Text": "పాఠం",
  "Instructions": "సూచనలు",
  "Remarks and notes": "వ్యాఖ్యలు, గమనికలు",
  "Click a merge field to put it where the cursor is. Each document fills it with the student's or staff member's own details.": "ఒక మెర్జ్ ఖాళీని క్లిక్ చేస్తే అది కర్సర్ ఉన్న చోట వస్తుంది. ప్రతి పత్రం దాన్ని విద్యార్థి లేదా సిబ్బంది సొంత వివరాలతో నింపుతుంది.",
  "Numbered details": "సంఖ్యలున్న వివరాలు",
  "The rows of the certificate, in the order the board's format lists them.": "సర్టిఫికెట్ వరుసలు, బోర్డు ఫార్మాట్‌లో ఉన్న క్రమంలో.",
  "Signatures and footer": "సంతకాలు, ఫుటర్",
  "QR code to check the document": "పత్రాన్ని తనిఖీ చేసే QR కోడ్",
  "Holds the document's number, so anyone can check it with the school.": "అందులో పత్రం నంబర్ ఉంటుంది, తద్వారా ఎవరైనా స్కూల్‌తో తనిఖీ చేయవచ్చు.",
  "Barcode": "బార్‌కోడ్",
  "For scanners at the library or the counter.": "గ్రంథాలయం లేదా కౌంటర్ స్కానర్ల కోసం.",
