  "Role name can be at most 60 characters.": "పాత్ర పేరు గరిష్ఠంగా 60 అక్షరాలు ఉండవచ్చు.",
  "The School Admin role must keep Full access to Settings, so someone can always manage logins and roles.": "స్కూల్ అడ్మిన్ పాత్రకు సెట్టింగ్‌లపై పూర్తి అనుమతి ఉండాలి, తద్వారా ఎవరో ఒకరు లాగిన్‌లు, పాత్రలు నిర్వహించగలరు.",
  "This role was not found. It may have been archived.": "ఈ పాత్ర దొరకలేదు. ఆర్కైవ్ అయి ఉండవచ్చు.",
