  "Your school was not found.": "మీ స్కూల్ దొరకలేదు.",
  "Choose the board.": "బోర్డు ఎంచుకోండి.",
  "The second board must be a different board.": "రెండో బోర్డు వేరే బోర్డు అయి ఉండాలి.",
