  "Where the devices are": "పరికరాలు ఎక్కడ ఉన్నాయి",
  "Main gate": "ప్రధాన ద్వారం",
  "Not connected": "కలపలేదు",
  "Only Transport, Library, Inventory and Hostel can be switched on or off. The other modules are always on.": "రవాణా, గ్రంథాలయం, స్టాక్, హాస్టల్ మాత్రమే ఆన్ లేదా ఆఫ్ చేయవచ్చు. మిగతా మాడ్యూల్స్ ఎప్పుడూ ఆన్.",
  "Choose the first day of the week.": "వారంలో మొదటి రోజు ఎంచుకోండి.",
  "Choose the roll number order.": "రోల్ నంబర్ క్రమం ఎంచుకోండి.",
  "Choose at least one role that may use the AI assistant.": "AI సహాయకుడిని వాడగల కనీసం ఒక పాత్ర ఎంచుకోండి.",
  "This feature was not found.": "ఈ సదుపాయం దొరకలేదు.",
  "Switch on the AI assistant first.": "ముందుగా AI సహాయకుడిని ఆన్ చేయండి.",
  "Choose a school-type template.": "స్కూల్ రకం టెంప్లేట్ ఎంచుకోండి.",
  "Details are complete.": "వివరాలు పూర్తయ్యాయి.",
  "Connect this integration first.": "ముందుగా ఈ అనుసంధానాన్ని కలపండి.",
  "This person was not found in your school.": "ఈ వ్యక్తి మీ స్కూల్‌లో దొరకలేదు.",
  "Choose at least one role.": "కనీసం ఒక పాత్ర ఎంచుకోండి.",
  "One of the chosen roles was not found. Reload the page and choose again.": "ఎంచుకున్న పాత్రల్లో ఒకటి దొరకలేదు. పేజీని మళ్ళీ లోడ్ చేసి మళ్ళీ ఎంచుకోండి.",
  "Choose the campus.": "క్యాంపస్ ఎంచుకోండి.",
  "That campus was not found.": "ఆ క్యాంపస్ దొరకలేదు.",
  "At least one School Admin must remain. Add another School Admin first.": "కనీసం ఒక స్కూల్ అడ్మిన్ ఉండాలి. ముందు మరో స్కూల్ అడ్మిన్‌ను జోడించండి.",
  "That staff member was not found.": "ఆ సిబ్బంది దొరకలేదు.",
  "This person has already set a password, so they do not need an invite.": "ఈ వ్యక్తి ఇప్పటికే పాస్‌వర్డ్ పెట్టుకున్నారు, కాబట్టి ఆహ్వానం అవసరం లేదు.",
  "This person is disabled in your school. Enable them first.": "ఈ వ్యక్తి మీ స్కూల్‌లో ఆపివేయబడ్డారు. ముందు ఆన్ చేయండి.",
  "At least one School Admin must remain with Settings. Add another School Admin first.": "సెట్టింగ్‌లతో కనీసం ఒక స్కూల్ అడ్మిన్ ఉండాలి. ముందు మరో స్కూల్ అడ్మిన్‌ను జోడించండి.",
  "You cannot disable your own login. Ask another School Admin.": "మీ సొంత లాగిన్‌ను ఆపలేరు. మరో స్కూల్ అడ్మిన్‌ను అడగండి.",
  "This person is already disabled.": "ఈ వ్యక్తి ఇప్పటికే ఆపివేయబడ్డారు.",
  "This person is already active.": "ఈ వ్యక్తి ఇప్పటికే చురుకుగా ఉన్నారు.",
  "The roles this person had are archived or switched off. Open the person and give them a role after enabling.": "ఈ వ్యక్తికి ఉన్న పాత్రలు ఆర్కైవ్ లేదా ఆఫ్ అయ్యాయి. ఆన్ చేశాక వ్యక్తిని తెరిచి పాత్ర ఇవ్వండి.",
  "Only a School Admin or the Principal can reset two-step login.": "స్కూల్ అడ్మిన్ లేదా ప్రిన్సిపల్ మాత్రమే రెండు-దశల లాగిన్ రీసెట్ చేయగలరు.",
  "You cannot reset your own two-step login. Ask another School Admin or the Principal.": "మీ సొంత రెండు-దశల లాగిన్ రీసెట్ చేయలేరు. మరో స్కూల్ అడ్మిన్ లేదా ప్రిన్సిపల్‌ను అడగండి.",
  "Choose the reason.": "కారణం ఎంచుకోండి.",
  "Say how the person was confirmed, for example \"in person at the office\".": "వ్యక్తిని ఎలా నిర్ధారించారో చెప్పండి, ఉదా. \"ఆఫీసులో ప్రత్యక్షంగా\".",
  "Your two-step login was reset. You will set it up again at your next sign-in.": "మీ రెండు-దశల లాగిన్ రీసెట్ అయింది. తదుపరి సైన్ ఇన్‌లో మళ్ళీ ఏర్పాటు చేసుకుంటారు.",
  "That student was not found.": "ఆ విద్యార్థి దొరకలేదు.",
  "This login also works in another school, so only the person can change these details, in My profile.": "ఈ లాగిన్ మరో స్కూల్‌లో కూడా పనిచేస్తుంది, కాబట్టి ఈ వివరాలను ఆ వ్యక్తి మాత్రమే నా ప్రొఫైల్‌లో మార్చగలరు.",
  "The expiry date must be after the issue date.": "గడువు తేదీ జారీ తేదీ తర్వాత ఉండాలి.",
  "Choose who can see it.": "ఎవరు చూడగలరో ఎంచుకోండి.",
  "One of the chosen roles was not found.": "ఎంచుకున్న పాత్రల్లో ఒకటి దొరకలేదు.",
  "Choose the document type.": "పత్ర రకం ఎంచుకోండి.",
  "This document was not found.": "ఈ పత్రం దొరకలేదు.",
  "This document is archived. Restore it first.": "ఈ పత్రం ఆర్కైవ్‌లో ఉంది. ముందు తిరిగి తేండి.",
  "A sharing link can work for 1 to 30 days.": "పంచుకునే లింక్ 1 నుండి 30 రోజులు పనిచేయవచ్చు.",
  "This document is archived. Restore it before sharing.": "ఈ పత్రం ఆర్కైవ్‌లో ఉంది. పంచుకునే ముందు తిరిగి తేండి.",
  "This document has no file yet.": "ఈ పత్రానికి ఇంకా ఫైల్ లేదు.",
  "Use of the child's data (DPDP Act 2023)": "పిల్లల డేటా వాడకం (DPDP చట్టం 2023)",
