  "Set each person's user number on the machine to their staff ID or admission number; Auto-match then links them. Use the push or ADMS setting, or a small connector on a school computer. Keep the machine's clock right.": "యంత్రంలో ప్రతి వ్యక్తి యూజర్ నంబర్‌ను వారి స్టాఫ్ ID లేదా అడ్మిషన్ నంబర్‌గా పెట్టండి; ఆటో-మ్యాచ్ వారిని కలుపుతుంది. పుష్ లేదా ADMS సెట్టింగ్, లేదా స్కూల్ కంప్యూటర్‌పై చిన్న కనెక్టర్ వాడండి. యంత్రం గడియారం సరిగ్గా ఉంచండి.",
