  "is not locked yet (it locks at": "ఇంకా లాక్ కాలేదు (ఇది లాక్ అయ్యే సమయం",
  "). You can still change it directly in": "). మీరు ఇప్పటికీ నేరుగా మార్చవచ్చు:",
  "There are no": "ఇక్కడ",
  "here.": "లేవు.",
