  "Who can change marks after the lock": "లాక్ తర్వాత గుర్తులు ఎవరు మార్చగలరు",
  "Everyone else sends a correction request to Approvals. The original stays in the audit log.": "మిగతా అందరూ ఆమోదాలకు సవరణ అభ్యర్థన పంపుతారు. అసలుది ఆడిట్ లాగ్‌లో ఉంటుంది.",
  "Nobody. Every change after the lock is a correction request.": "ఎవరూ కాదు. లాక్ తర్వాత ప్రతి మార్పు సవరణ అభ్యర్థనే.",
  "Change the message": "సందేశం మార్చండి",
  "The “Absent today” message is switched off in Communication, Message Settings.": "“ఈ రోజు గైర్హాజరు” సందేశం కమ్యూనికేషన్, సందేశ సెట్టింగ్‌లలో ఆఫ్ చేయబడింది.",
  "No channel that can carry it is switched on. Connect WhatsApp or SMS in Settings, Messaging.": "దాన్ని పంపగల ఏ ఛానల్ ఆన్‌లో లేదు. సెట్టింగ్‌లు, మెసేజింగ్‌లో WhatsApp లేదా SMS కనెక్ట్ చేయండి.",
  "Switch on “Absence message to parents” below to send it after each register.": "ప్రతి రిజిస్టర్ తర్వాత పంపడానికి క్రింద “తల్లిదండ్రులకు గైర్హాజరు సందేశం” ఆన్ చేయండి.",
  "Message parents get": "తల్లిదండ్రులకు వచ్చే సందేశం",
