  "Give a reason of at least 5 characters, so the approver understands the change.": "ఆమోదించేవారు మార్పును అర్థం చేసుకునేలా కనీసం 5 అక్షరాల కారణం ఇవ్వండి.",
  "Choose at least one person and their new status.": "కనీసం ఒక వ్యక్తిని మరియు వారి కొత్త స్థితిని ఎంచుకోండి.",
  "Choose the class.": "తరగతి ఎంచుకోండి.",
