  "Forest Green": "అటవీ ఆకుపచ్చ",
  "Only the School Admin or the Principal can change QR check-in.": "స్కూల్ అడ్మిన్ లేదా ప్రిన్సిపాల్ మాత్రమే QR చెక్-ఇన్ మార్చగలరు.",
  "Name is needed, for example \"Main entrance\".": "పేరు అవసరం, ఉదాహరణకు \"ప్రధాన ప్రవేశ ద్వారం\".",
  "Choose who checks in with this QR.": "ఈ QRతో ఎవరు చెక్-ఇన్ చేస్తారో ఎంచుకోండి.",
  "Choose a changing or fixed QR.": "మారే లేదా స్థిర QR ఎంచుకోండి.",
  "Expiry must be in the future.": "గడువు భవిష్యత్తులో ఉండాలి.",
  "This QR was not found.": "ఈ QR కనబడలేదు.",
  "Latitude must be a number between -90 and 90, like 17.385044.": "అక్షాంశం -90 నుండి 90 మధ్య సంఖ్య అయి ఉండాలి, 17.385044 లాగా.",
  "Longitude must be a number between -180 and 180, like 78.486671.": "రేఖాంశం -180 నుండి 180 మధ్య సంఖ్య అయి ఉండాలి, 78.486671 లాగా.",
  "Sign in first.": "ముందుగా సైన్ ఇన్ చేయండి.",
  "Your login is not linked to a staff or student record, so you cannot check in. Ask the office.": "మీ లాగిన్ స్టాఫ్ లేదా విద్యార్థి రికార్డ్‌కు కలపబడలేదు, కాబట్టి మీరు చెక్-ఇన్ చేయలేరు. ఆఫీసును అడగండి.",
  "QR check-in is switched off for this school.": "ఈ స్కూల్‌కు QR చెక్-ఇన్ ఆఫ్ చేయబడింది.",
  "This QR is not valid today. Scan the QR at the school entrance.": "ఈ QR ఈ రోజు చెల్లదు. స్కూల్ ప్రవేశ ద్వారం వద్ద QR స్కాన్ చేయండి.",
  "This QR has been stopped. Ask the office.": "ఈ QR ఆపివేయబడింది. ఆఫీసును అడగండి.",
  "This QR has expired. Ask the office for the new one.": "ఈ QR గడువు ముగిసింది. కొత్తది కోసం ఆఫీసును అడగండి.",
  "This QR is for another campus.": "ఈ QR మరో క్యాంపస్‌ది.",
  "Mobile check-in is not on for you.": "మీకు మొబైల్ చెక్-ఇన్ ఆన్‌లో లేదు.",
  "Mobile check-in is switched off for staff in Attendance Settings.": "హాజరు సెట్టింగ్‌లలో సిబ్బందికి మొబైల్ చెక్-ఇన్ ఆఫ్ చేయబడింది.",
  "The campus area is not set yet, so mobile check-in cannot work. Ask the School Admin.": "క్యాంపస్ ప్రాంతం ఇంకా సెట్ కాలేదు, కాబట్టి మొబైల్ చెక్-ఇన్ పనిచేయదు. స్కూల్ అడ్మిన్‌ను అడగండి.",
  "Your attendance for today is already marked.": "ఈ రోజు మీ హాజరు ఇప్పటికే నమోదైంది.",
  "You are not in a class today. Ask the office.": "ఈ రోజు మీరు ఏ తరగతిలో లేరు. ఆఫీసును అడగండి.",
  "Only people who look after the whole school's attendance can send these reminders.": "మొత్తం స్కూల్ హాజరు చూసుకునే వారు మాత్రమే ఈ గుర్తుచేతలు పంపగలరు.",
  "There is no academic year running now.": "ఇప్పుడు ఏ విద్యా సంవత్సరం నడవడం లేదు.",
