  "No money was posted and no receipt was made. The parent can pay again by a new link.": "డబ్బు పోస్ట్ కాలేదు, రసీదు తయారు కాలేదు. తల్లిదండ్రులు కొత్త లింక్‌తో మళ్ళీ చెల్లించవచ్చు.",
  "It stays posted until it is decided in Approvals.": "ఆమోదాలలో నిర్ణయం అయ్యే వరకు ఇది పోస్ట్ అయి ఉంటుంది.",
