  "Payments are never deleted or edited. A wrong one is cancelled with a reason and stays on record.": "చెల్లింపులు ఎప్పుడూ తొలగించబడవు లేదా మార్చబడవు. తప్పు చెల్లింపు కారణంతో రద్దు చేయబడి రికార్డులో ఉంటుంది.",
