  "Type the go-live date on the go-live check first (Settings, Data Backup & Security, Switching to School OS).": "ముందుగా ప్రారంభ తనిఖీలో ప్రారంభ తేదీ టైప్ చేయండి (సెట్టింగ్‌లు, డేటా బ్యాకప్ & భద్రత, School OSకు మారడం).",
