  "Changing the payment date needs the \"change payment date\" permission. Ask the accountant.": "చెల్లింపు తేదీ మార్చడానికి \"చెల్లింపు తేదీ మార్చడం\" అనుమతి అవసరం. అకౌంటెంట్‌ను అడగండి.",
