  "Advance payments": "అడ్వాన్స్ చెల్లింపులు",
  "Parents may pay more than the current dues; the extra is held as advance and used for the next installments.": "తల్లిదండ్రులు ప్రస్తుత బాకీల కంటే ఎక్కువ చెల్లించవచ్చు; అదనపుది అడ్వాన్స్‌గా ఉంచబడి తదుపరి వాయిదాలకు వాడబడుతుంది.",
  "Verify payments before posting": "పోస్ట్ చేసే ముందు చెల్లింపులు తనిఖీ చేయండి",
  "Payments in the modes you choose arrive as Waiting for verification until approved.": "మీరు ఎంచుకున్న పద్ధతులలో చెల్లింపులు ఆమోదించే వరకు తనిఖీ కోసం వేచి ఉన్నట్లు వస్తాయి.",
