  "Each fee head goes to a chosen bank account; receipts and the Day Book show it.": "ప్రతి ఫీజు శీర్షిక ఎంచుకున్న బ్యాంక్ ఖాతాకు వెళ్తుంది; రసీదులు మరియు డే బుక్ దాన్ని చూపుతాయి.",
  "Category-wise fees": "వర్గం వారీ ఫీజులు",
  "Different fee amounts for different student categories.": "వేర్వేరు విద్యార్థి వర్గాలకు వేర్వేరు ఫీజు మొత్తాలు.",
  "Scholarship types, applied to a student's fees as a reduction.": "స్కాలర్‌షిప్ రకాలు, విద్యార్థి ఫీజులకు తగ్గింపుగా వర్తిస్తాయి.",
  "Collection forecast": "వసూలు అంచనా",
  "A suggested collection for the next 3 months from installments due and past payments. Shown while the AI assistant is on (Settings, Modules On/Off), to the roles chosen there.": "చెల్లించాల్సిన వాయిదాలు మరియు గత చెల్లింపుల నుండి తదుపరి 3 నెలలకు సూచించిన వసూలు. AI సహాయకుడు ఆన్‌లో ఉన్నప్పుడు (సెట్టింగ్‌లు, మాడ్యూల్స్ ఆన్/ఆఫ్) అక్కడ ఎంచుకున్న పాత్రలకు చూపబడుతుంది.",
  "Promise to pay": "చెల్లిస్తామన్న మాట",
  "On a call, note the date (and amount) a family promises to pay. Automatic reminders to them pause until then; a broken promise puts them back at the top of Defaulters.": "కాల్‌లో, కుటుంబం చెల్లిస్తామన్న తేదీ (మరియు మొత్తం) నోట్ చేయండి. అప్పటివరకు వారికి ఆటోమేటిక్ గుర్తుచేతలు ఆగుతాయి; మాట తప్పితే వారు బాకీదారులలో మళ్ళీ పైకి వస్తారు.",
  "This applicant was not found, or has no application fee.": "ఈ దరఖాస్తుదారు కనబడలేదు, లేదా దరఖాస్తు ఫీజు లేదు.",
  "Set up the academic year in Academic Management first.": "ముందుగా అకడమిక్ నిర్వహణలో విద్యా సంవత్సరం సెట్ చేయండి.",
  "Choose a fee head.": "ఫీజు శీర్షిక ఎంచుకోండి.",
  "Fee opening balances (old dues)": "ఫీజు ప్రారంభ బ్యాలెన్స్‌లు (పాత బాకీలు)",
  "Leave empty for Old dues": "పాత బాకీల కోసం ఖాళీగా వదలండి",
  "Empty or 0 for a student with no old dues: that row is left out": "పాత బాకీలు లేని విద్యార్థికి ఖాళీ లేదా 0: ఆ వరుస వదిలివేయబడుతుంది",
