  "for": "కోసం",
  "No change": "మార్పు లేదు",
  "changes": "మార్పులు",
  "Check again": "మళ్ళీ తనిఖీ చేయండి",
  "Check the changes": "మార్పులు తనిఖీ చేయండి",
  "Choose other students": "ఇతర విద్యార్థులను ఎంచుకోండి",
  "Issue certificate": "సర్టిఫికెట్ జారీ చేయండి",
  "· asked": "· అడిగారు",
  "It gets the next number in the series and can then be issued.": "దీనికి సిరీస్‌లో తదుపరి నంబర్ వస్తుంది, తర్వాత జారీ చేయవచ్చు.",
  "The person who asked is told, with your reason.": "అడిగిన వ్యక్తికి మీ కారణంతో తెలియజేయబడుతుంది.",
  "Waiting for the approver": "ఆమోదించేవారి కోసం వేచి ఉంది",
