  "No signatories are set up. Add the Principal's name and signature in": "సంతకం చేసేవారు సెట్ కాలేదు. ప్రిన్సిపాల్ పేరు మరియు సంతకం ఇక్కడ జోడించండి:",
  "Settings, Document Designs": "సెట్టింగ్‌లు, డాక్యుమెంట్ డిజైన్‌లు",
