  "This phone belongs to a parent already on record.": "ఈ ఫోన్ ఇప్పటికే నమోదైన తల్లిదండ్రులది.",
  "Link": "కలపండి",
  "Add as a new parent": "కొత్త తల్లిదండ్రులుగా జోడించండి",
  "Numbers": "నంబర్లు",
  "Photo, identifiers, emergency contacts and the school's extra fields are added on the Student Profile after saving.": "ఫోటో, గుర్తింపు నంబర్లు, అత్యవసర సంప్రదింపులు మరియు స్కూల్ అదనపు ఫీల్డ్‌లు సేవ్ చేసిన తర్వాత విద్యార్థి ప్రొఫైల్‌లో జోడించబడతాయి.",
  "For students who did not come through Admission Management, for example when moving from your old software. Only the main details are needed now; the rest is filled on the profile.": "ప్రవేశాల నిర్వహణ ద్వారా రాని విద్యార్థుల కోసం, ఉదాహరణకు పాత సాఫ్ట్‌వేర్ నుండి మారేటప్పుడు. ఇప్పుడు ప్రధాన వివరాలు మాత్రమే అవసరం; మిగతావి ప్రొఫైల్‌లో నింపబడతాయి.",
  "Open the academic year and add classes and sections in": "విద్యా సంవత్సరం తెరిచి తరగతులు మరియు సెక్షన్లు ఇక్కడ జోడించండి:",
  ", then come back.": ", తర్వాత తిరిగి రండి.",
  "The list uses the published final results, and the attendance and fees recorded so far, and updates by itself. Saved batches move students into": "జాబితా ప్రచురించిన తుది ఫలితాలు, ఇప్పటివరకు నమోదైన హాజరు మరియు ఫీజులను వాడుతుంది, దానంతట అదే నవీకరించబడుతుంది. సేవ్ చేసిన బ్యాచ్‌లు విద్యార్థులను ఇక్కడికి తరలిస్తాయి:",
  "Open Academic Management": "అకడమిక్ నిర్వహణ తెరవండి",
  "Students can be split across sections in the next step": "తదుపరి దశలో విద్యార్థులను సెక్షన్లలో విభజించవచ్చు",
