  "APAAR and PEN are exported from Reports & Analytics, Government Reports.": "APAAR మరియు PEN నివేదికలు & విశ్లేషణ, ప్రభుత్వ నివేదికల నుండి ఎగుమతి అవుతాయి.",
  "The card number is recorded when the ID card is printed, on Certificates & ID Cards.": "ID కార్డ్ ప్రింట్ అయినప్పుడు, సర్టిఫికెట్లు & ID కార్డులలో కార్డ్ నంబర్ నమోదవుతుంది.",
