  "Change section": "సెక్షన్ మార్చండి",
  "; to move class, use Promotion.": "; తరగతి మార్చడానికి “తర్వాతి తరగతికి పంపడం” వాడండి.",
  "Aadhaar is changed with the personal details. Identifier types are set in Student Settings.": "ఆధార్ వ్యక్తిగత వివరాలతో మారుతుంది. గుర్తింపు రకాలు విద్యార్థి సెట్టింగ్‌లలో సెట్ అవుతాయి.",
  "The school has no extra fields for students. They are added in": "స్కూల్‌కు విద్యార్థుల కోసం అదనపు ఫీల్డ్‌లు లేవు. అవి ఇక్కడ జోడించబడతాయి:",
  "Settings, Forms & Approvals": "సెట్టింగ్‌లు, ఫారమ్‌లు & ఆమోదాలు",
  "Only the School Admin or Principal can change a restriction.": "స్కూల్ అడ్మిన్ లేదా ప్రిన్సిపాల్ మాత్రమే పరిమితిని మార్చగలరు.",
  "Open the year in Academic Management first.": "ముందుగా అకడమిక్ నిర్వహణలో సంవత్సరం తెరవండి.",
  "Add another section in Academic Management to move students between sections. To move class, use Promotion.": "విద్యార్థులను సెక్షన్ల మధ్య తరలించడానికి అకడమిక్ నిర్వహణలో మరో సెక్షన్ జోడించండి. తరగతి మార్చడానికి “తర్వాతి తరగతికి పంపడం” వాడండి.",
  "Now in": "ఇప్పుడు దీనిలో",
  ". The student gets the next free roll number in the new section; the old section stays in the history.": ". విద్యార్థికి కొత్త సెక్షన్‌లో తదుపరి ఖాళీ రోల్ నంబర్ వస్తుంది; పాత సెక్షన్ చరిత్రలో ఉంటుంది.",
  "has no class in": "కి దీనిలో తరగతి లేదు:",
  ", for example after re-admission. Choose the class and section.": ", ఉదాహరణకు మళ్ళీ అడ్మిషన్ తర్వాత. తరగతి మరియు సెక్షన్ ఎంచుకోండి.",
  "A re-admission request is waiting in": "మళ్ళీ అడ్మిషన్ అభ్యర్థన వేచి ఉంది ఇక్కడ:",
  ". The status changes when it is approved.": ". ఆమోదించినప్పుడు స్థితి మారుతుంది.",
  "No change can be made here. Promotion is done on the Promotion page, and leaving on Leaving & Alumni.": "ఇక్కడ మార్పు చేయలేరు. తర్వాతి తరగతికి పంపడం దాని పేజీలో, వదిలివెళ్ళడం “వదిలివెళ్ళడం & పూర్వ విద్యార్థులు”లో జరుగుతుంది.",
  "Only the allowed changes are offered. Promotion, transfer, withdrawal and graduation are done on their own pages.": "అనుమతించిన మార్పులు మాత్రమే చూపబడతాయి. ప్రమోషన్, బదిలీ, ఉపసంహరణ మరియు ఉత్తీర్ణత వాటి సొంత పేజీలలో జరుగుతాయి.",
  "chosen": "ఎంచుకున్నవి",
  "Search students": "విద్యార్థులను వెతకండి",
