  "Choose all": "అన్నీ ఎంచుకోండి",
  "No student found. Try the admission number.": "విద్యార్థి కనబడలేదు. అడ్మిషన్ నంబర్ ప్రయత్నించండి.",
  "Career notes, entrance exams, college applications, scholarships and alumni mentors.": "కెరీర్ నోట్స్, ప్రవేశ పరీక్షలు, కాలేజీ దరఖాస్తులు, స్కాలర్‌షిప్‌లు మరియు పూర్వ విద్యార్థి మార్గదర్శకులు.",
