  "Sends the primary contact the school's Behaviour note by WhatsApp (or SMS). The message names the type and date, not the details.": "ప్రధాన సంప్రదింపుకు WhatsApp (లేదా SMS) ద్వారా స్కూల్ ప్రవర్తన నోట్ పంపుతుంది. సందేశంలో రకం మరియు తేదీ ఉంటాయి, వివరాలు కాదు.",
