  "No behaviour records this year": "ఈ సంవత్సరం ప్రవర్తన రికార్డులు లేవు",
  "Incidents, warnings, suspensions, rewards and recognition show here. Three taps on a phone: student, type, note.": "సంఘటనలు, హెచ్చరికలు, సస్పెన్షన్లు, బహుమతులు మరియు గుర్తింపులు ఇక్కడ కనిపిస్తాయి. ఫోన్‌లో మూడు ట్యాప్‌లు: విద్యార్థి, రకం, నోట్.",
