  "Anyone whose WhatsApp or app message fails, or is not read within the wait time, gets the same message by SMS. Backup SMS use the message type’s SMS template with a DLT template ID and use credits.": "WhatsApp లేదా యాప్ సందేశం విఫలమైన, లేదా వేచి ఉండే సమయంలో చదవని ఎవరికైనా అదే సందేశం SMS ద్వారా వస్తుంది. బ్యాకప్ SMSలు సందేశ రకం యొక్క DLT టెంప్లేట్ ID ఉన్న SMS టెంప్లేట్ వాడతాయి, క్రెడిట్‌లు వాడతాయి.",
  "Wait": "వేచి ఉండండి",
  "Retry limit for failed messages": "విఫలమైన సందేశాలకు మళ్ళీ పంపే పరిమితి",
  "How many times a failed message can be retried.": "విఫలమైన సందేశాన్ని ఎన్నిసార్లు మళ్ళీ పంపవచ్చు.",
  "Notice approval rule": "నోటీసు ఆమోద నియమం",
  "The Principal and School Admin publish without approval.": "ప్రిన్సిపాల్ మరియు స్కూల్ అడ్మిన్ ఆమోదం లేకుండా ప్రచురిస్తారు.",
  "Save delivery settings": "చేరిక సెట్టింగ్‌లు సేవ్ చేయండి",
  "Reply time limits (response-time targets)": "జవాబు సమయ పరిమితులు (ప్రతిస్పందన సమయ లక్ష్యాలు)",
  "Escalate overdue queries to": "గడువు దాటిన ప్రశ్నలను వీరికి పంపండి",
  "Ask the requester to rate how it was handled (1 to 5) when a query is closed": "ప్రశ్న మూసినప్పుడు అది ఎలా నిర్వహించబడిందో రేట్ చేయమని (1 నుండి 5) అడిగినవారిని అడగండి",
  "Save query rules": "ప్రశ్న నియమాలు సేవ్ చేయండి",
  "Default owner": "డిఫాల్ట్ బాధ్యులు",
  "Add topic": "విషయం జోడించండి",
  "Record a change": "మార్పు నమోదు చేయండి",
  "Find a parent": "తల్లిదండ్రులను కనుగొనండి",
  "Choose another": "మరొకటి ఎంచుకోండి",
  "How the parent told the school": "తల్లిదండ్రులు స్కూల్‌కు ఎలా చెప్పారు",
  "No parent has opted out. Emergency messages always reach everyone.": "ఏ తల్లిదండ్రులూ వద్దనలేదు. అత్యవసర సందేశాలు ఎప్పుడూ అందరికీ చేరతాయి.",
  "· since": "· నుండి",
  "They will get normal messages again, recorded as a phone call. To record another way, find the parent above.": "వారికి మళ్ళీ సాధారణ సందేశాలు వస్తాయి, ఫోన్ కాల్‌గా నమోదవుతుంది. వేరే విధంగా నమోదు చేయడానికి పైన తల్లిదండ్రులను కనుగొనండి.",
  "It can no longer be chosen in Send Message. Messages already sent to it are not changed.": "ఇది ఇక సందేశం పంపండిలో ఎంచుకోబడదు. దీనికి ఇప్పటికే పంపిన సందేశాలు మారవు.",
  "Parent Link is": "పేరెంట్ లింక్",
  "for the school": "స్కూల్ కోసం",
  "What it shows": "ఇది ఏమి చూపుతుంది",
  "Fees and Pay, receipts, attendance this month, the datesheet and report cards are added here as their modules are switched on.": "ఫీజులు మరియు చెల్లింపు, రసీదులు, ఈ నెల హాజరు, డేట్‌షీట్ మరియు రిపోర్ట్ కార్డులు వాటి మాడ్యూల్స్ ఆన్ అయినప్పుడు ఇక్కడ జోడించబడతాయి.",
  "Send links automatically when an admission is approved": "అడ్మిషన్ ఆమోదించినప్పుడు లింక్‌లు దానంతట అవే పంపండి",
  "template": "టెంప్లేట్",
  "One-time code valid for": "ఒక్కసారి కోడ్ ఇంత సమయం చెల్లుతుంది",
  "minutes": "నిమిషాలు",
  "A verified phone stays verified for": "ధృవీకరించిన ఫోన్ ఇంత కాలం ధృవీకరించబడి ఉంటుంది",
  "days": "రోజులు",
  "Save Parent Link settings": "పేరెంట్ లింక్ సెట్టింగ్‌లు సేవ్ చేయండి",
  "What each automatic message sent, to whom, and why.": "ప్రతి ఆటోమేటిక్ సందేశం ఏమి పంపింది, ఎవరికి, ఎందుకు.",
  "Switch them on under Optional pages in Message Settings.": "వీటిని సందేశ సెట్టింగ్‌లలో ఐచ్ఛిక పేజీల క్రింద ఆన్ చేయండి.",
  "New survey": "కొత్త సర్వే",
  "Start from an example": "ఒక ఉదాహరణ నుండి ప్రారంభించండి",
