  "Approve or reject with remarks, keep the waiting list and confirm admissions": "వ్యాఖ్యలతో ఆమోదించండి లేదా తిరస్కరించండి, వెయిటింగ్ లిస్ట్ ఉంచండి మరియు అడ్మిషన్లు ధృవీకరించండి",
  "Decisions here need approval (Settings, Forms & Approvals)": "ఇక్కడి నిర్ణయాలకు ఆమోదం అవసరం (సెట్టింగ్‌లు, ఫారమ్‌లు & ఆమోదాలు)",
