  "Nobody else can approve this yet. Ask your School Admin to add a Principal (Settings, Users & Permissions).": "ఇంకా మరెవరూ దీన్ని ఆమోదించలేరు. ప్రిన్సిపాల్‌ను జోడించమని మీ స్కూల్ అడ్మిన్‌ను అడగండి (సెట్టింగ్‌లు, యూజర్లు & అనుమతులు).",
