  "This request is waiting for someone else.": "ఈ అభ్యర్థన వేరొకరి కోసం వేచి ఉంది.",
  "Give a reason of at least 5 characters, so the person knows why.": "వ్యక్తికి ఎందుకో తెలిసేలా కనీసం 5 అక్షరాల కారణం ఇవ్వండి.",
