  "Only the person who decided this request, the Principal or the School Admin can finish it.": "ఈ అభ్యర్థనను నిర్ణయించినవారు, ప్రిన్సిపాల్ లేదా స్కూల్ అడ్మిన్ మాత్రమే దీన్ని పూర్తి చేయగలరు.",
  "This request is already finished: its record has moved on. Nothing was changed.": "ఈ అభ్యర్థన ఇప్పటికే పూర్తైంది: దాని రికార్డ్ ముందుకు వెళ్ళింది. ఏమీ మారలేదు.",
  "School OS could not finish this request: its record did not move on. Nothing was changed. Please tell DREAM TEAM support.": "School OS ఈ అభ్యర్థనను పూర్తి చేయలేకపోయింది: దాని రికార్డ్ ముందుకు వెళ్ళలేదు. ఏమీ మారలేదు. దయచేసి DREAM TEAM సపోర్ట్‌కు చెప్పండి.",
