  "Who is below the pass mark in {class}?": "{class}లో పాస్ మార్కు కంటే తక్కువ ఉన్నవారు ఎవరు?",
  "Which classes have marks below the pass mark?": "పాస్ మార్కు కంటే తక్కువ మార్కులు ఉన్న తరగతులు ఏవి?",
