  "done. Each step opens the right page. Come back here from the Dashboard.": "పూర్తయ్యాయి. ప్రతి దశ సరైన పేజీని తెరుస్తుంది. డాష్‌బోర్డ్ నుండి ఇక్కడికి తిరిగి రండి.",
  "Bring students and staff from Excel. Every row is checked before anything is added.": "Excel నుండి విద్యార్థులు మరియు సిబ్బందిని తీసుకురండి. ఏదైనా జోడించే ముందు ప్రతి వరుస తనిఖీ అవుతుంది.",
