  "Sent on": "పంపిన తేదీ",
  ". Students’ fees change only when it is approved. To change it, withdraw the request in Approvals.": ". ఆమోదించినప్పుడే విద్యార్థుల ఫీజులు మారతాయి. మార్చడానికి ఆమోదాలలో అభ్యర్థనను ఉపసంహరించండి.",
  "Changes here are not on students’ fees until you publish": "ప్రచురించే వరకు ఇక్కడి మార్పులు విద్యార్థుల ఫీజులపై ఉండవు",
