  "+ Add": "+ జోడించండి",
  "Progress already logged stays in history.": "ఇప్పటికే నమోదైన పురోగతి చరిత్రలో ఉంటుంది.",
  "Under": "దీని కింద",
  "One item a line. No dash for a unit, one dash for a chapter, two for a lesson, three for a topic. Add a planned end date after a bar. Copy a column from Excel and add the dashes, or type it.": "ఒక్కో వరుసలో ఒక అంశం. యూనిట్‌కు డాష్ లేదు, అధ్యాయానికి ఒక డాష్, పాఠానికి రెండు, అంశానికి మూడు. బార్ తర్వాత ప్లాన్ చేసిన ముగింపు తేదీ జోడించండి. Excel నుండి కాలమ్ కాపీ చేసి డాష్‌లు జోడించండి, లేదా టైప్ చేయండి.",
  "Copy from another class or year": "మరో తరగతి లేదా సంవత్సరం నుండి కాపీ చేయండి",
