  "Open the period master": "పీరియడ్ మాస్టర్ తెరవండి",
  "Click a period to change it. Clashes are checked as you choose.": "మార్చడానికి పీరియడ్‌పై క్లిక్ చేయండి. మీరు ఎంచుకునేటప్పుడే ఘర్షణలు తనిఖీ అవుతాయి.",
  "Your login is not linked to a staff record. Ask the office to link it in Staff & HR.": "మీ లాగిన్ స్టాఫ్ రికార్డ్‌కు కలపబడలేదు. స్టాఫ్ & HRలో కలపమని ఆఫీసును అడగండి.",
