  "It will no longer be offered for new datesheets. Exams that already use it keep it. Adding the same name again brings it back.": "ఇది కొత్త డేట్‌షీట్‌లకు చూపబడదు. ఇప్పటికే వాడే పరీక్షలు దీన్ని ఉంచుకుంటాయి. అదే పేరు మళ్ళీ జోడిస్తే తిరిగి వస్తుంది.",
