  "It cannot be marked paid until approved. You will be told when it is decided.": "ఆమోదించే వరకు దీన్ని చెల్లించినట్లు గుర్తించలేము. నిర్ణయమైనప్పుడు మీకు తెలియజేయబడుతుంది.",
  "Paid now": "ఇప్పుడే చెల్లించారు",
