  "Moving from old software or registers.": "పాత సాఫ్ట్‌వేర్ లేదా రిజిస్టర్ల నుండి మారుతున్నారు.",
  "Record income": "ఆదాయం నమోదు చేయండి",
  "No income posted this financial year.": "ఈ ఆర్థిక సంవత్సరం ఆదాయం పోస్ట్ కాలేదు.",
  ". Drafts are not in the Day Book.": ". డ్రాఫ్ట్‌లు డే బుక్‌లో ఉండవు.",
  "Fees are not recorded here. They reach the Day Book from Fees by themselves.": "ఫీజులు ఇక్కడ నమోదు కావు. అవి ఫీజుల నుండి దానంతట అవే డే బుక్‌కు చేరతాయి.",
  "A posted entry cannot be changed. Cancel it with a reason and record it again.": "పోస్ట్ అయిన ఎంట్రీని మార్చలేము. కారణంతో రద్దు చేసి మళ్ళీ నమోదు చేయండి.",
  "Each posted entry has a receipt to print.": "పోస్ట్ అయిన ప్రతి ఎంట్రీకి ప్రింట్ చేయడానికి రసీదు ఉంది.",
