  "Main": "ప్రధాన",
  "heads have a Tally ledger name · the others use their own name": "శీర్షికలకు Tally లెడ్జర్ పేరు ఉంది · ఇతరులు సొంత పేరు వాడతాయి",
  "Ledger names": "లెడ్జర్ పేర్లు",
