  "first: months close in order.": "ముందుగా: నెలలు క్రమంలో మూసివేయబడతాయి.",
  "Before closing": "మూసే ముందు",
  "What closing does": "మూసివేయడం ఏమి చేస్తుంది",
  "Nothing dated in": "ఈ తేదీతో ఏదీ",
  "can be added, changed or cancelled any more: no fee payment, income, expense, salary payment, journal entry or money move. A mistake found later goes in as an adjustment in": "ఇక జోడించలేము, మార్చలేము లేదా రద్దు చేయలేము: ఫీజు చెల్లింపు, ఆదాయం, ఖర్చు, జీతం చెల్లింపు, జర్నల్ ఎంట్రీ లేదా డబ్బు బదిలీ ఏదీ కాదు. తర్వాత కనబడిన తప్పు సర్దుబాటుగా దీనిలోకి వెళ్తుంది:",
  "Each account's closing balance is its opening balance on": "ప్రతి ఖాతా ముగింపు బ్యాలెన్స్ దాని ప్రారంభ బ్యాలెన్స్, తేదీ",
  "Income and expense heads start": "ఆదాయం మరియు ఖర్చు శీర్షికలు ప్రారంభమవుతాయి",
  "at ₹0.": "₹0 వద్ద.",
  "of 6 ·": "6లో ·",
  "Give advance or loan": "అడ్వాన్స్ లేదా రుణం ఇవ్వండి",
  "Switch them on in Salary Settings to give new ones. Open ones are still recovered.": "కొత్తవి ఇవ్వడానికి జీతం సెట్టింగ్‌లలో ఆన్ చేయండి. తెరిచి ఉన్నవి ఇప్పటికీ వసూలవుతాయి.",
  "repays the balance of": "బ్యాలెన్స్ తిరిగి చెల్లిస్తారు",
  "in cash. A receipt goes in the Day Book and no more is deducted from salary.": "నగదుగా. డే బుక్‌లో రసీదు వెళ్తుంది, జీతం నుండి ఇక కోత ఉండదు.",
  "Open a month": "ఒక నెల తెరవండి",
  "Attendance and approved leave up to": "ఈ తేదీ వరకు హాజరు మరియు ఆమోదించిన సెలవు",
  "are in. They keep coming in by themselves until the month is sent for approval.": "వచ్చాయి. నెల ఆమోదానికి పంపే వరకు అవి దానంతట అవే వస్తూనే ఉంటాయి.",
  "Not worked out yet. Calculate to bring in attendance, leave and structures.": "ఇంకా లెక్కించలేదు. హాజరు, సెలవు మరియు నిర్మాణాలు తీసుకురావడానికి లెక్కించండి.",
  "salary slips are made and each staff member was told. Amounts are frozen. Pay the staff, then mark it paid.": "జీతం స్లిప్‌లు తయారై ప్రతి సిబ్బంది సభ్యుడికి తెలియజేయబడింది. మొత్తాలు స్థిరం. సిబ్బందికి చెల్లించి, చెల్లించినట్లు గుర్తించండి.",
  "One salary entry is in the Day Book on the date paid. Corrections go in next month as an adjustment.": "చెల్లించిన తేదీన డే బుక్‌లో ఒక జీతం ఎంట్రీ ఉంటుంది. సవరణలు తర్వాతి నెలలో సర్దుబాటుగా వెళ్తాయి.",
  "This run never changes. A correction is an adjustment, with a reason, in a following month.": "ఈ రన్ ఎప్పుడూ మారదు. సవరణ తర్వాతి నెలలో కారణంతో సర్దుబాటు.",
  "View only. Check that leave and attendance reach the salary; the Accountant runs it.": "చూడడానికి మాత్రమే. సెలవు మరియు హాజరు జీతానికి చేరుతున్నాయో తనిఖీ చేయండి; అకౌంటెంట్ దీన్ని నడుపుతారు.",
  "Add adjustment": "సర్దుబాటు జోడించండి",
