  "(gross": "(స్థూల",
  "Attendance after today is not in yet. Days after today, and leave or attendance changed after approval, come into next month’s salary by themselves as arrears or a deduction, with the reason.": "ఈ రోజు తర్వాత హాజరు ఇంకా రాలేదు. ఈ రోజు తర్వాతి రోజులు, మరియు ఆమోదం తర్వాత మారిన సెలవు లేదా హాజరు, కారణంతో తర్వాతి నెల జీతంలో బకాయిలుగా లేదా కోతగా దానంతట అవే వస్తాయి.",
