  "No applications yet.": "ఇంకా దరఖాస్తులు లేవు.",
  "Resume": "రెజ్యూమె",
  "My appraisal": "నా మూల్యాంకనం",
  "· waiting for your review": "· మీ సమీక్ష కోసం వేచి ఉంది",
  "Open a vacancy": "ఖాళీ తెరవండి",
  "Add application": "దరఖాస్తు జోడించండి",
  "Interviewers": "ఇంటర్వ్యూ చేసేవారు",
  "Start appraisal": "మూల్యాంకనం ప్రారంభించండి",
