  "Record promotion": "పదోన్నతి నమోదు చేయండి",
  "No departments yet. Add one so leave goes to the right head.": "ఇంకా విభాగాలు లేవు. సెలవు సరైన అధిపతికి వెళ్ళేలా ఒకటి జోడించండి.",
  "No staff leave types yet.": "ఇంకా సిబ్బంది సెలవు రకాలు లేవు.",
  "Head of department": "విభాగ అధిపతి",
  "Next approver from the rule": "నియమం నుండి తదుపరి ఆమోదించేవారు",
  "Nobody approves their own leave. When the head asks for leave, it goes to the next approver.": "ఎవరూ తమ సెలవును తామే ఆమోదించరు. అధిపతి సెలవు అడిగినప్పుడు, అది తదుపరి ఆమోదించేవారికి వెళ్తుంది.",
