  "An SMS can only be sent from a template. Add a \"Message to staff (SMS)\" template in Communication, Message Templates.": "SMS టెంప్లేట్ నుండి మాత్రమే పంపవచ్చు. కమ్యూనికేషన్, సందేశ టెంప్లేట్‌లలో \"సిబ్బందికి సందేశం (SMS)\" టెంప్లేట్ జోడించండి.",
