  "Choose what is being paid: PF, ESI, Professional Tax or TDS.": "ఏమి చెల్లిస్తున్నారో ఎంచుకోండి: PF, ESI, వృత్తి పన్ను లేదా TDS.",
  "Enter the challan or reference number.": "చలాన్ లేదా రిఫరెన్స్ నంబర్ నమోదు చేయండి.",
  "Salary changes start on the 1st of a month. Pick the 1st.": "జీతం మార్పులు నెల 1వ తేదీన ప్రారంభమవుతాయి. 1వ తేదీ ఎంచుకోండి.",
  "TDS cannot be below ₹0.": "TDS ₹0 కంటే తక్కువ ఉండకూడదు.",
  "TDS is more than the monthly gross. Check the amount.": "TDS నెలవారీ స్థూల కంటే ఎక్కువ. మొత్తం తనిఖీ చేయండి.",
  "Add a salary structure for this person first.": "ముందుగా ఈ వ్యక్తికి జీతం నిర్మాణం జోడించండి.",
  "Choose the staff to revise.": "సవరించాల్సిన సిబ్బందిని ఎంచుకోండి.",
  "None of them has a salary structure to revise.": "వారిలో ఎవరికీ సవరించడానికి జీతం నిర్మాణం లేదు.",
  "Salary to date": "ఇప్పటివరకు జీతం",
  "Gross salary paid this financial year before School OS, in rupees.": "ఈ ఆర్థిక సంవత్సరం School OS ముందు చెల్లించిన స్థూల జీతం, రూపాయలలో.",
  "The staff member's own PF deducted, in rupees.": "సిబ్బంది సభ్యుడి సొంత PF కోత, రూపాయలలో.",
  "The staff member's own ESI deducted, in rupees.": "సిబ్బంది సభ్యుడి సొంత ESI కోత, రూపాయలలో.",
  "Income tax deducted at source, in rupees.": "మూలం వద్ద కోసిన ఆదాయపు పన్ను, రూపాయలలో.",
