  "The last month these totals cover. Leave empty for the month before your go-live date.": "ఈ మొత్తాలు కవర్ చేసే చివరి నెల. మీ ప్రారంభ తేదీకి ముందు నెలకు ఖాళీగా వదలండి.",
  "Give the account a name, such as Trust account.": "ఖాతాకు పేరు ఇవ్వండి, ట్రస్ట్ ఖాతా లాగా.",
  "Name can be at most 60 characters.": "పేరు గరిష్టంగా 60 అక్షరాలు ఉండవచ్చు.",
  "Account number is 6 to 18 digits.": "ఖాతా నంబర్ 6 నుండి 18 అంకెలు.",
  "IFSC is 11 characters, like SBIN0001234.": "IFSC 11 అక్షరాలు, SBIN0001234 లాగా.",
  "This account was not found.": "ఈ ఖాతా కనబడలేదు.",
  "Choose another account as the main bank account first.": "ముందుగా మరో ఖాతాను ప్రధాన బ్యాంక్ ఖాతాగా ఎంచుకోండి.",
  "Cash in hand cannot be archived.": "చేతిలో నగదును ఆర్కైవ్ చేయలేము.",
  "Choose two different accounts.": "రెండు వేర్వేరు ఖాతాలు ఎంచుకోండి.",
  "Choose where the money comes from.": "డబ్బు ఎక్కడి నుండి వస్తుందో ఎంచుకోండి.",
  "Choose where the money goes.": "డబ్బు ఎక్కడికి వెళ్తుందో ఎంచుకోండి.",
  "This money move was not found or is already cancelled.": "ఈ డబ్బు బదిలీ కనబడలేదు లేదా ఇప్పటికే రద్దు అయింది.",
  "Choose the account.": "ఖాతా ఎంచుకోండి.",
  "Opening balance cannot be below ₹0.": "ప్రారంభ బ్యాలెన్స్ ₹0 కంటే తక్కువ ఉండకూడదు.",
  "A change to this opening balance is already waiting for approval.": "ఈ ప్రారంభ బ్యాలెన్స్ మార్పు ఇప్పటికే ఆమోదం కోసం వేచి ఉంది.",
  "That is the opening balance already set.": "ఇదే ఇప్పటికే సెట్ చేసిన ప్రారంభ బ్యాలెన్స్.",
  "Budget must be more than ₹0.": "బడ్జెట్ ₹0 కంటే ఎక్కువ ఉండాలి.",
