  "Choose year, term or month.": "సంవత్సరం, టర్మ్ లేదా నెల ఎంచుకోండి.",
  "This budget was not found.": "ఈ బడ్జెట్ కనబడలేదు.",
  "The new amount is the same as the current one.": "కొత్త మొత్తం ప్రస్తుతదానితో సమానం.",
  "Choose a different year to copy from.": "కాపీ చేయడానికి వేరే సంవత్సరం ఎంచుకోండి.",
  "That year has no budgets to copy.": "ఆ సంవత్సరం కాపీ చేయడానికి బడ్జెట్‌లు లేవు.",
  "This budget was not found. It may already be removed.": "ఈ బడ్జెట్ కనబడలేదు. ఇది ఇప్పటికే తీసివేయబడి ఉండవచ్చు.",
  "Cash counted cannot be less than ₹0.": "లెక్కించిన నగదు ₹0 కంటే తక్కువ ఉండకూడదు.",
  "This closed day was not found.": "ఈ మూసిన రోజు కనబడలేదు.",
  "Its month is closed, so the day stays locked.": "దాని నెల మూసివేయబడింది, కాబట్టి రోజు లాక్‌లోనే ఉంటుంది.",
  "Only the person who closed the day can undo it.": "రోజు మూసివేసిన వ్యక్తి మాత్రమే రద్దు చేయగలరు.",
  "It is too late to undo. Ask the Principal to reopen the day.": "రద్దు చేయడానికి చాలా ఆలస్యమైంది. రోజును మళ్ళీ తెరవమని ప్రిన్సిపాల్‌ను అడగండి.",
  "You closed this day, so someone else reopens it: the Principal or the School Admin.": "ఈ రోజును మీరు మూసివేశారు, కాబట్టి వేరొకరు మళ్ళీ తెరుస్తారు: ప్రిన్సిపాల్ లేదా స్కూల్ అడ్మిన్.",
  "Say why the day is reopened, in a few words.": "రోజును ఎందుకు మళ్ళీ తెరుస్తున్నారో కొన్ని మాటల్లో చెప్పండి.",
  "Nobody has the Accountant role to remind. Give someone the role in Settings, Users & Permissions.": "గుర్తుచేయడానికి ఎవరికీ అకౌంటెంట్ పాత్ర లేదు. సెట్టింగ్‌లు, యూజర్లు & అనుమతులలో ఎవరికైనా ఆ పాత్ర ఇవ్వండి.",
  "Online fees": "ఆన్‌లైన్ ఫీజులు",
  "Daycare": "డేకేర్",
  "Other fee types": "ఇతర ఫీజు రకాలు",
  "Other income": "ఇతర ఆదాయం",
  "Choose the expense head.": "ఖర్చు శీర్షిక ఎంచుకోండి.",
  "Choose a vendor from the list, or add a new one.": "జాబితా నుండి విక్రేతను ఎంచుకోండి, లేదా కొత్తవారిని జోడించండి.",
  "A vendor bill needs the vendor.": "విక్రేత బిల్‌కు విక్రేత అవసరం.",
  "Enter the bill number from the vendor's bill.": "విక్రేత బిల్ నుండి బిల్ నంబర్ నమోదు చేయండి.",
  "Only a draft can be sent for approval.": "డ్రాఫ్ట్ మాత్రమే ఆమోదానికి పంపవచ్చు.",
  "Posted entries cannot be edited. Cancel and record again?": "పోస్ట్ అయిన ఎంట్రీలను మార్చలేము. రద్దు చేసి మళ్ళీ నమోదు చేయాలా?",
  "Brought in from old software. It cannot be changed.": "పాత సాఫ్ట్‌వేర్ నుండి తెచ్చారు. దీన్ని మార్చలేము.",
  "Brought in from old software. Not in the Day Book.": "పాత సాఫ్ట్‌వేర్ నుండి తెచ్చారు. డే బుక్‌లో లేదు.",
  "This expense is already paid.": "ఈ ఖర్చు ఇప్పటికే చెల్లించారు.",
  "Only an approved expense can be paid.": "ఆమోదించిన ఖర్చు మాత్రమే చెల్లించవచ్చు.",
  "Only vendor bills can be paid in parts. Pay the full amount.": "విక్రేత బిల్లులు మాత్రమే భాగాలుగా చెల్లించవచ్చు. పూర్తి మొత్తం చెల్లించండి.",
  "Choose the cash or bank account the money comes from.": "డబ్బు వచ్చే నగదు లేదా బ్యాంక్ ఖాతా ఎంచుకోండి.",
  "This expense is already cancelled.": "ఈ ఖర్చు ఇప్పటికే రద్దు అయింది.",
  "Brought in from old software. Undo the whole import from the import history if it was wrong.": "పాత సాఫ్ట్‌వేర్ నుండి తెచ్చారు. తప్పైతే దిగుమతి చరిత్ర నుండి మొత్తం దిగుమతిని రద్దు చేయండి.",
  "This expense is cancelled.": "ఈ ఖర్చు రద్దు అయింది.",
  "A bill is already attached.": "బిల్ ఇప్పటికే జత చేయబడింది.",
  "Vendor name is needed.": "విక్రేత పేరు అవసరం.",
  "Open the expense": "ఖర్చు తెరవండి",
  "Open opening balances": "ప్రారంభ బ్యాలెన్స్‌లు తెరవండి",
  "Past expenses (brought in)": "పాత ఖర్చులు (తెచ్చినవి)",
  "A head in Finance Settings, by name or code": "ఫైనాన్స్ సెట్టింగ్‌లలో ఒక శీర్షిక, పేరు లేదా కోడ్‌తో",
  "A cost centre, when cost centres are on": "ఖర్చు కేంద్రం, ఖర్చు కేంద్రాలు ఆన్‌లో ఉన్నప్పుడు",
  "Choose the income head.": "ఆదాయ శీర్షిక ఎంచుకోండి.",
  "Fees are recorded in Fee Management, not here. Choose another income head.": "ఫీజులు ఫీజుల నిర్వహణలో నమోదవుతాయి, ఇక్కడ కాదు. వేరే ఆదాయ శీర్షిక ఎంచుకోండి.",
  "Say who the money came from.": "డబ్బు ఎవరి నుండి వచ్చిందో చెప్పండి.",
  "Choose the mode.": "పద్ధతి ఎంచుకోండి.",
  "This income was not found.": "ఈ ఆదాయం కనబడలేదు.",
