  "Only posted income has a receipt.": "పోస్ట్ అయిన ఆదాయానికి మాత్రమే రసీదు ఉంటుంది.",
  "Write a narration: what this entry is for.": "వివరణ రాయండి: ఈ ఎంట్రీ దేనికోసం.",
  "A journal entry needs at least two lines.": "జర్నల్ ఎంట్రీకి కనీసం రెండు వరుసలు అవసరం.",
  "Amounts cannot be below ₹0.": "మొత్తాలు ₹0 కంటే తక్కువ ఉండకూడదు.",
  "A line is either a debit or a credit, not both.": "వరుస డెబిట్ లేదా క్రెడిట్, రెండూ కాదు.",
  "A head on this entry was not found or is archived. Choose it again.": "ఈ ఎంట్రీలోని ఒక శీర్షిక కనబడలేదు లేదా ఆర్కైవ్ అయింది. మళ్ళీ ఎంచుకోండి.",
  "Give a reason for reversing.": "రివర్స్ చేయడానికి కారణం ఇవ్వండి.",
  "This journal entry was not found.": "ఈ జర్నల్ ఎంట్రీ కనబడలేదు.",
  "This entry is itself a reversal. Add a new entry instead.": "ఈ ఎంట్రీ స్వయంగా రివర్సల్. బదులుగా కొత్త ఎంట్రీ జోడించండి.",
  "This entry is already reversed.": "ఈ ఎంట్రీ ఇప్పటికే రివర్స్ అయింది.",
  "Income and expense": "ఆదాయం మరియు ఖర్చు",
  "By head and by month": "శీర్షిక మరియు నెల వారీగా",
  "Profit and loss": "లాభం మరియు నష్టం",
  "Income less expenses for the period": "కాలానికి ఆదాయం నుండి ఖర్చులు తీసివేస్తే",
  "Expense report": "ఖర్చు నివేదిక",
  "By head, vendor, month or approver": "శీర్షిక, విక్రేత, నెల లేదా ఆమోదించేవారి వారీగా",
  "Department-wise expenses": "విభాగం వారీ ఖర్చులు",
  "By department (cost centre)": "విభాగం (ఖర్చు కేంద్రం) వారీగా",
  "Pending expenses": "పెండింగ్ ఖర్చులు",
  "Waiting for approval or payment": "ఆమోదం లేదా చెల్లింపు కోసం వేచి ఉన్నాయి",
  "Bill due": "బిల్ గడువు",
  "Cash book and bank book": "నగదు పుస్తకం మరియు బ్యాంక్ పుస్తకం",
  "Opening, receipts, payments, closing": "ప్రారంభ, రసీదులు, చెల్లింపులు, ముగింపు",
  "Closing": "ముగింపు",
  "Payments include money moved between accounts, such as cash deposited in the bank. Day by day detail is on Cash & Bank.": "చెల్లింపులలో ఖాతాల మధ్య తరలించిన డబ్బు ఉంటుంది, బ్యాంక్‌లో జమ చేసిన నగదు లాంటిది. రోజు వారీ వివరాలు నగదు & బ్యాంక్‌లో ఉన్నాయి.",
  "Budget against actual": "వాస్తవానికి ఎదురుగా బడ్జెట్",
  "Needs budgets switched on": "బడ్జెట్‌లు ఆన్ చేయాలి",
  "Remaining": "మిగిలింది",
  "Alert": "హెచ్చరిక",
  "Trial balance": "ట్రయల్ బ్యాలెన్స్",
  "Every account’s balance (full accounts)": "ప్రతి ఖాతా బ్యాలెన్స్ (పూర్తి ఖాతాలు)",
  "Day Book for a range": "ఒక పరిధికి డే బుక్",
  "Every day’s totals": "ప్రతి రోజు మొత్తాలు",
  "The financial year starts in April, January or June.": "ఆర్థిక సంవత్సరం ఏప్రిల్, జనవరి లేదా జూన్‌లో ప్రారంభమవుతుంది.",
  "The amount cannot be below ₹0.": "మొత్తం ₹0 కంటే తక్కువ ఉండకూడదు.",
  "Use capital letters, numbers, / or -, up to 12 characters, like INC/.": "పెద్ద అక్షరాలు, అంకెలు, / లేదా - వాడండి, 12 అక్షరాల వరకు, INC/ లాగా.",
  "Choose Income or Expense.": "ఆదాయం లేదా ఖర్చు ఎంచుకోండి.",
  "Give the head a name.": "శీర్షికకు పేరు ఇవ్వండి.",
  "Codes have 4 digits.": "కోడ్‌లకు 4 అంకెలు ఉంటాయి.",
  "Choose the group.": "గ్రూప్ ఎంచుకోండి.",
  "This head was not found.": "ఈ శీర్షిక కనబడలేదు.",
  "Give the department a name, like “Science labs”.": "విభాగానికి పేరు ఇవ్వండి, “సైన్స్ ల్యాబ్‌లు” లాగా.",
  "Closing the day is the accountant's work.": "రోజు మూసివేయడం అకౌంటెంట్ పని.",
  "Yearly budgets by head and department, with budget against actual and alerts at 80% and 100%.": "శీర్షిక మరియు విభాగం వారీగా వార్షిక బడ్జెట్‌లు, వాస్తవానికి ఎదురుగా బడ్జెట్ మరియు 80%, 100% వద్ద హెచ్చరికలతో.",
  "Journal entries, the general ledger, trial balance, payables and receivables, for schools keeping full accounts.": "పూర్తి ఖాతాలు ఉంచే స్కూళ్ళకు జర్నల్ ఎంట్రీలు, జనరల్ లెడ్జర్, ట్రయల్ బ్యాలెన్స్, చెల్లించాల్సినవి మరియు రావాల్సినవి.",
  "Tag expenses and budgets to departments or units.": "ఖర్చులు మరియు బడ్జెట్‌లను విభాగాలు లేదా యూనిట్లకు ట్యాగ్ చేయండి.",
  "Record a vendor's bill with bill number and due date, and pay it later in parts.": "విక్రేత బిల్‌ను బిల్ నంబర్ మరియు గడువు తేదీతో నమోదు చేసి, తర్వాత భాగాలుగా చెల్లించండి.",
  "For a school starting part way through the year: earlier expenses come in read-only as Brought in and never reach the Day Book.": "సంవత్సరం మధ్యలో ప్రారంభించే స్కూల్ కోసం: ముందటి ఖర్చులు “తెచ్చినవి”గా చదవడానికి మాత్రమే వస్తాయి, ఎప్పుడూ డే బుక్‌కు చేరవు.",
  "Map heads to Tally ledgers and download vouchers for Tally.": "శీర్షికలను Tally లెడ్జర్లకు కలిపి Tally కోసం వోచర్లు డౌన్‌లోడ్ చేయండి.",
  "Fee payments (full)": "ఫీజు చెల్లింపులు (పూర్తి)",
