  "No expenses paid on this date.": "ఈ తేదీన ఖర్చులు చెల్లించలేదు.",
  "No salary paid on this date.": "ఈ తేదీన జీతం చెల్లించలేదు.",
  "Refunds and reversals": "రీఫండ్‌లు మరియు రివర్సల్‌లు",
